fn distinct_chars(s: Str) -> Int {
    let seen = vec()
    for c in chars(s) {
        if !contains(seen, c) {
            seen = push(seen, c)
        }
    }
    len(seen)
}
fn main() {
    let text = "mississippi"
    print(count_s(text))
    print(distinct_chars(text))
}

